// === Tab: mySketch ===
let firework = [];
let colors = ['#111d5e', '#c70039', '#f37121', '#c0e218'];
let g;

function setup() {
	createCanvas(windowWidth, windowHeight);


}

function draw() {
	fill(0, 10);
	rect(0, 0, width, height);

	g = createVector(0, 0.01);

	if(firework.length > 0) {
		for(let i = 0; i < firework.length; i++) {
			firework[i].show();
			firework[i].move();
			firework[i].applyForce(g);

			if(firework[i].vel.y > 0) firework[i].boom();
			if(firework[i].isDead()) firework.splice(i, 1);
		}
	}
}

function mousePressed() {
	for(let i = 0; i < 100; i++) {
		firework.push(new Ball((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 5, colors[i%colors.length]));
	}
}

class Ball {
	constructor(x, y, s_, c_) {
		this.pos = createVector(x, y);
		this.vel = createVector(0, -1);
		this.acel = createVector(0, -1);
		this.s = s_;
		this.c = c_;
		this.aux = true;
		this.a = 255;
	}

	show() {
		noStroke();
		fill(this.c);
		ellipse(this.pos.x, this.pos.y, this.s, this.s);

		if(!this.aux) this.a -= random(2, 4);
	}

	move() {
		this.vel.add(this.acel);
		this.vel.limit(5);
		this.pos.add(this.vel);
		this.acel.mult(0);
	}

	applyForce(f) {
		this.acel.add(f);
	}

	boom() {
		if(this.aux) {
			this.acel = p5.Vector.random2D();
			this.acel.normalize();
			this.acel.mult(random(2));
			this.aux = false;
		}
	}

	isDead() {
		if(this.a < 10) return true;
		else return false;
	}
}

